      $('[data-password]').onclick=e=>{const input=$('#auth-password'),show=input.type==='password';input.type=show?'text':'password';e.currentTarget.textContent=show?'隐藏':'显示';e.currentTarget.setAttribute('aria-label',show?'隐藏密码':'显示密码');};$('#auth-example').onsubmit=e=>{e.preventDefault();$('#auth-error').textContent='此页为设计样例，不会发送账号或密码。';};return;
