    if(currentSub==='profile-detail')body=`<div class="profile-card"><span class="profile-avatar">林</span><div><h1>林小满</h1><p class="subtle">产品部 · 产品设计组</p><span class="pill">员工</span></div></div>`+group('个人介绍',profileEditing?'<textarea aria-label="个人介绍">把复杂的问题整理清楚，和团队一起做好每一次交付。</textarea>':'<p>把复杂的问题整理清楚，和团队一起做好每一次交付。</p>')+group('联系与资料','<dl>'+[['phone','电话','未提供'],['email','邮箱','未提供'],['person','性别','未提供'],['birthday','年龄','未提供'],['employment','入职日期','2026年9月1日'],['tenure','工龄','2个月']].map(([icon,k,v],i)=>`<div class="detail-row profile-field"><img src="../assets/generated_ui/sunshine/icons/${icon}.png" alt=""><dt>${k}</dt><dd>${profileEditing&&i<4?`<input aria-label="${k}" placeholder="未提供">`:v}</dd></div>`).join('')+'</dl>')+(profileEditing?'<div class="sheet-actions"><button class="secondary" data-profile-cancel>取消</button><button class="primary" data-profile-save>保存</button></div>':'');
