    if(currentSub==='review-detail')body='<div class="detail-top"><span class="pill">待审核</span><h1>品牌素材发布申请</h1><p class="subtle">陈晨提交 · 11月6日 10:30</p></div>'+group('申请内容','<p>发布新一期品牌规范与协作模板，便于团队使用统一素材。</p>')+group('变更说明','<p>补充移动端组件规范与使用说明。</p>')+group('审核记录','<div class="activity"><p>陈晨提交申请</p><time>11月6日 10:30</time></div><div class="activity"><p>等待直属上级审核</p></div>')+'<div class="detail-bottom"><button class="secondary" data-subpage="feedback-form">驳回并说明</button><button class="primary" data-example-action>通过</button></div>';
